#!/usr/bin/env bash
# Question 2: Pod ${Q2_CLAIM}-app stuck. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q2_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q2_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q2_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: v1
kind: PersistentVolume
metadata:
  name: ${Q2_CLAIM}-pv
spec:
  capacity: { storage: 1Gi }
  accessModes: [ReadWriteOnce]
  persistentVolumeReclaimPolicy: Retain
  storageClassName: manual
  hostPath:
    path: /srv/${Q2_CLAIM}
    type: DirectoryOrCreate
EOF
sc=manual mode=ReadWriteOnce size=500Mi

case "${Q2_FAULT}" in
  storageclass-mismatch)
    sc=fast
    ;;
  access-mode-mismatch)
    mode=ReadWriteMany
    ;;
  claim-too-large)
    size=2Gi
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac

kubectl apply -f - <<< '{"apiVersion":"v1","kind":"List","items":[{"apiVersion":"v1","kind":"PersistentVolumeClaim","metadata":{"name":"'"${Q2_CLAIM}"'","namespace":"'"${Q2_NS}"'"},"spec":{"storageClassName":"'"$sc"'","accessModes":["'"$mode"'"],"resources":{"requests":{"storage":"'"$size"'"}}}},{"apiVersion":"v1","kind":"Pod","metadata":{"name":"'"${Q2_CLAIM}"'-app","namespace":"'"${Q2_NS}"'"},"spec":{"containers":[{"name":"app","image":"busybox:1.36","command":["sleep","1d"],"volumeMounts":[{"name":"data","mountPath":"/data"}]}],"volumes":[{"name":"data","persistentVolumeClaim":{"claimName":"'"${Q2_CLAIM}"'"}}]}}]}'
sleep 10
[[ "$(kubectl -n "${Q2_NS}" get pvc "${Q2_CLAIM}" -o jsonpath='{.status.phase}')" == Pending ]]
